import{_ as a,o as i,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Lumberjacking","description":"","frontmatter":{},"headers":[],"relativePath":"en/game-design/professions/lumberjacking.md","filePath":"en/game-design/professions/lumberjacking.md"}'),o={name:"en/game-design/professions/lumberjacking.md"};function r(l,e,s,d,c,h){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="lumberjacking" tabindex="-1">Lumberjacking <a class="header-anchor" href="#lumberjacking" aria-label="Permalink to &quot;Lumberjacking&quot;">​</a></h1><p><strong>Design status:</strong> Proposed; all mechanics, examples and technique paths below remain candidates. <strong>Implementation:</strong> no implementation of this redesign is established by this documentation batch. <strong>Availability:</strong> not established. <strong>Verification:</strong> documentation review only; no gameplay test. <strong>Reviewed:</strong> 2026-10-09 for public projection; design status and mechanics preserved from the canonical specification.</p><p><a href="/Syrolands-Public/en/guide/professions/lumberjacking.html">Player-facing overview</a> · <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Purpose and profession loop <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Permalink to &quot;Purpose and profession loop&quot;">​</a></h2><p>Lumberjacking should be forestry/resource knowledge, not only &quot;hit tree for logs&quot;.</p><h3 id="tree-state" tabindex="-1">Tree state <a class="header-anchor" href="#tree-state" aria-label="Permalink to &quot;Tree state&quot;">​</a></h3><ul><li>species;</li><li>maturity;</li><li>condition;</li><li>resource amount;</li></ul><p>with other behavior derived rather than fully persisted.</p><p>Tree felling should physically alter the world. A felled tree can occupy multiple tiles and temporarily block/alter navigation.</p><h3 id="world-and-tactical-utility" tabindex="-1">World and tactical utility <a class="header-anchor" href="#world-and-tactical-utility" aria-label="Permalink to &quot;World and tactical utility&quot;">​</a></h3><ul><li>using felled trees to block routes/chokepoints;</li><li>battlefield or siege utility;</li><li>possibly improvised bridges in specific situations;</li><li>interaction with structures/terrain via simplified tile-based rules.</li></ul><p>Do not require full physics simulation. Design can assume discrete/tile-based fall resolution.</p><h3 id="tree-knowledge" tabindex="-1">Tree knowledge <a class="header-anchor" href="#tree-knowledge" aria-label="Permalink to &quot;Tree knowledge&quot;">​</a></h3><ul><li>species;</li><li>maturity;</li><li>health/disease;</li><li>approximate timber quality;</li><li>regional ecology.</li></ul><h3 id="potential-felling-approaches" tabindex="-1">Potential felling approaches <a class="header-anchor" href="#potential-felling-approaches" aria-label="Permalink to &quot;Potential felling approaches&quot;">​</a></h3><ul><li>quick felling;</li><li>controlled felling;</li><li>selective cutting.</li></ul><p>Selection must have tangible economic/time value, otherwise players will simply clear-cut everything.</p><h3 id="value-of-knowledge" tabindex="-1">Value of knowledge <a class="header-anchor" href="#value-of-knowledge" aria-label="Permalink to &quot;Value of knowledge&quot;">​</a></h3><ul><li>better yield/time;</li><li>better material selection;</li><li>lower tool wear;</li><li>better recovery of useful timber;</li><li>avoiding low-value diseased/poor trees.</li></ul><p>Regional regeneration/overharvest can matter, but exact living-world simulation remains technical/proposed.</p><h2 id="knowledge-and-specialization" tabindex="-1">Knowledge and specialization <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Permalink to &quot;Knowledge and specialization&quot;">​</a></h2><p><strong>Forester&#39;s Journal.</strong> Species, maturity, health/disease, approximate timber quality and regional ecology are learnable expertise. Controlled felling and selective cutting should have economic/time value.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Shared progression, production and economy <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Permalink to &quot;Shared progression, production and economy&quot;">​</a></h2><p>The <a href="/Syrolands-Public/en/game-design/characters/skills-and-skillcap.html">character skill framework</a> owns teaching and cap/gain direction. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html">Profession System</a> owns craft discovery, knowledge sharing, manual mastery, batch production, commissions and multidimensional reputation. Those rules are not independently redefined here. The <a href="/Syrolands-Public/en/game-design/items/itemization-and-craft-quality.html">quality specification</a> owns the shared result envelope and rare item properties.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Related skills and field interactions <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Permalink to &quot;Related skills and field interactions&quot;">​</a></h2><p>Carpentry uses selected timber; Camping and Cooking can use fuel knowledge. Tracking may interpret disturbed terrain, while world/material rules bound forestry, fire and recovery.</p><p><a href="/Syrolands-Public/en/game-design/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/en/game-design/professions/cooking.html">Cooking</a> · <a href="/Syrolands-Public/en/game-design/living-world.html#knowledge-professions-and-traces">Camping and Tracking</a> · <a href="/Syrolands-Public/en/game-design/living-world.html#trees-and-forestry">Trees and forestry</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstraction and technical boundary <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Permalink to &quot;Abstraction and technical boundary&quot;">​</a></h2><p>Keep only state and feedback that support meaningful decisions. The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#performance-abstraction-and-authority">shared abstraction/authority constraints</a> and living-world architecture apply; persistence requires a separate technical design. Nothing here selects packet IDs, schemas, timers, UI assets or runtime algorithms.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><p>Felling direction, footprints, hazards and ownership; route-blocking duration and protected spaces; when bridges are permitted; selective-cutting incentives; regional recovery and overharvest. The later Forestry-skill candidate is not automatically a new skill alongside this Lumberjacking direction.</p><p>The <a href="/Syrolands-Public/en/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">shared reconciliation register</a> owns cross-system conflicts. Existing combat experiments and evidence do not validate this profession redesign.</p>',32)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
